		{ "🚧 Stuck at level {number1}! Go to Menu (B) → Skills & Growth tab (Passives · Training) to break through.", "🚧 Bloqué au niveau {number1} ! Allez dans le menu (B) → onglet Compétences et croissance (passif · entraînement) pour percer." },
		{ "💰 Not enough Gold. ({number1} needed) Earn Gold from field hunting / dungeons / Boss Rush / idle income", "💰 Pas assez d'or. ({number1} requis) Or via chasse / donjons / Boss Rush / revenus passifs" },
		{ "Zone {number1} · Meadow\n🌾 Adventure Begins · Rec. ⚡{number2}\nDanger ☠\n🌾 New set from here: Meadow's Guard Set", "Zone {number1} · Prairie\n🌾 L'aventure commence · Rec. ⚡{number2}\nDanger ☠\n🌾 Nouveau ensemble à partir d'ici : Ensemble de garde des prés" },
		{ "Limit Breaker   Title 『Limit Breaker』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Titre « Briseur de limites »\nVainquez {number1} boss lors d'une course de boss\n{number2} / {number3} Récompense : 🎫 {number4}" },
		{ "Deadeye: an enemy must be within {number1} range to lock on! (Camps are safe zones with no enemies", "Œil de mort : un ennemi doit être à portée {number1} pour le verrouiller ! (Les camps sont des zones sûres sans ennemis" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Sniper Rifle · Rusty Era +{number10}\n📍 Dungeon", "🎖 Niveau {number1} {number2} / {number3} EXP\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Gratuit aujourd'hui {number7}/{number8})\n⚡ Puissance {number9}\n⚔ Fusil de sniper · Ère rouillée +{number10}\n📍 Donjon" },
		{ "🌱 Beginner's Boon: +{number1}% damage and -{number2}% damage taken until you clear Zone {number3} (it fades by Lv {number4})", "🌱 Avantage pour débutants : +{number1}% de dégâts et -{number2}% de dégâts subis jusqu'à ce que vous ayez terminé la zone {number3} (il disparaît au niveau {number4})" },
		{ "🐾 Pet Lv.{number1}! New ability 🧲 Auto-Loot — Loot within a {number2} radius gets pulled in automatically", "🐾 Animal de compagnie niveau {number1} ! Nouvelle capacité 🧲 Butin automatique - Le butin situé dans un rayon de {number2} est récupéré automatiquement" },
		{ "Boss Hunter   Title 『Boss Hunter』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Titre du chasseur de boss\nVainquez {number1} boss lors d'une course de boss\n{number2} / {number3} Récompense : 🎫 {number4}" },
		{ "Unbreakable   Title 『Unbreakable』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Titre incassable 『Incassable』\nSurvivre pendant {number1} secondes dans le rush du boss\n{number2} / {number3} Récompense : 🎫 {number4}" },
		{ "Reduces training / breakthrough wait time by {number1} min (the skip bar fills instantly)", "Réduit le temps d'attente d'entraînement/de percée de {number1} minutes (la barre de saut se remplit instantanément)" },
		{ "🌟 A golden FEVER portal opened where the Colossus fell! Step in within {number1} seconds!", "🌟 Un portail FIÈVRE doré s'est ouvert là où le Colosse est tombé ! Entrez dans les {number1} secondes !" },
		{ "Survivor   Title 『Survivor』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Titre du survivant : « Survivant »\nSurvivre pendant {number1} secondes dans le rush du boss\n{number2} / {number3} Récompense : 🎫 {number4}" },
		{ "First Dungeon   Title 『Dungeon Newbie』\nClear {number1} dungeon(s)\n{number2} / {number3}   Reward: {number4} G + 🎫 {number5}", "Premier donjon - Titre \"Débutant du donjon\"\nTerminer {number1} donjon(s)\n{number2} / {number3} Récompense : {number4} G + 🎫 {number5}" },
		{ "Golden Hunter   Title 『Lucky Hunter』\nDefeat {number1} Golden Goblin(s)\n{number2} / {number3}   Reward: {number4} G", "Chasseur doré - Titre \"Chasseur chanceux\"\nÉliminer {number1} gobelins dorés\n{number2} / {number3} Récompense : {number4} G" },
